		public override void update()
		{
			base.update();
			if (player.x < 2400)
			{
				player.maxVelocity.x = 110 * Math.Abs(1200 - player.x) / 1200 + 30;
				cheerlover.maxVelocity.x = player.maxVelocity.x;
				if (player.x > 320)
				{
					player.jumpEnable = false;
				}

				FlxG.bgColor = (uint)(4281241856 - 65536 * Math.Floor((1200 - Math.Abs(1200 - player.x)) * 0.038) - 256 * Math.Floor((1200 - Math.Abs(1200 - player.x)) * 0.12));
			}

			if (!gecis)
			{
				if (player.x > 1200)
				{
					gecis = true;
					FlxG.playMusic(music2);
					FlxG.music.volume = 1;
				}
				else if (player.x > 1150)
				{
					FlxG.music.volume -= 0.01;
				}
			}

			if (isThereCheerlover)
			{
				FlxG.collide(level, cheerlover);
				FlxG.overlap<FlxSprite, FlxSprite>(cheerlover, interacts, overlapped);
			}

			cheerlover.isOnLeftOfHans = player.x - cheerlover.x > 8;
			cheerlover.isPlayerWalkinRight = player.velocity.x > 0;
			if (player.x > 160 && player.x < 2400)
			{
				narratorFollow.x = player.x - 90;
			}

			if (player.fading)
			{
				cheerlover.fading = true;
			}
		}

		public override void getWell()
		{
			FlxG.bgColor = 4281241856;
		}

		public override void nextLevel()
		{
			FlxG.switchState(new Level23());
		}
	}
